import{_ as a,o as i,c as e,a0 as t}from"./chunks/framework.BLL-IG04.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/getting-started.md","filePath":"tutorials/getting-started.md"}'),n={name:"tutorials/getting-started.md"};function l(h,s,o,d,p,c){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Point mimus at a repo&#39;s docs and see which claims are still true — docs-as-tests, in minutes.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The <code>mimus</code> command ships as a tamias pack (<code>libraries/mimus</code>): a generated <code>bins[]</code> shim → <code>tamias-driver-mimus cli</code> → the engine lib&#39;s <code>run_from</code>. With <code>tamias</code> installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/pack.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/mimus</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # from a checkout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia:mimus@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # org registry, once published</span></span></code></pre></div><p>A source build also works — the engine ships a compat <code>mimus</code> bin (not on crates.io; org policy):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/9aia/mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mimus</span></span></code></pre></div><h2 id="_1-init" tabindex="-1">1. Init <a class="header-anchor" href="#_1-init" aria-label="Permalink to &quot;1. Init&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>Writes a commented <code>mimus.toml</code> and a <code>rules/</code> dir. Defaults:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docs = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;README.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/**/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AGENTS.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project/**/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">comments = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cards = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.kuda/modules/*.yaml&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mechanical = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">semantic = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p><code>symbol</code> claims, <code>audit</code>, and <code>coverage</code> need a <a href="https://github.com/9aia/kuda" target="_blank" rel="noreferrer">kuda</a> index (<code>kuda sync</code>) — without one, the mechanical tier is paths + commands + rules.</p><h2 id="_2-check" tabindex="-1">2. Check <a class="header-anchor" href="#_2-check" aria-label="Permalink to &quot;2. Check&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Claim extraction scans every configured doc: backticked paths, shell commands, symbol names, counts, links. Each claim is verified against reality — the filesystem, PATH, the kuda index (symbol claims need <code>kuda sync</code>; without an index they&#39;re silence, not failures):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>README.md:42 [error] \`src/old_api.rs\` — ./src/old_api.rs does not exist</span></span>
<span class="line"><span>docs/guide.md:17 [warn] \`cargo bench\` — binary \`cargo-bench\` not found in PATH</span></span>
<span class="line"><span>2 violation(s)</span></span></code></pre></div><p>Exit code is <code>1</code> on any <code>error</code>-severity violation — docs drift becomes a gateable signal. <code>mimus report</code> lists violations with claim + evidence + fix.</p><h2 id="_3-make-a-claim-and-watch-it-get-caught" tabindex="-1">3. Make a claim and watch it get caught <a class="header-anchor" href="#_3-make-a-claim-and-watch-it-get-caught" aria-label="Permalink to &quot;3. Make a claim and watch it get caught&quot;">​</a></h2><p>Add a line to your README referencing a file that does not exist:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">See </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`nonexistent/dead.rs\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for the implementation.</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>README.md:N [error] \`nonexistent/dead.rs\` — ./nonexistent/dead.rs does not exist</span></span></code></pre></div><p>Every violation is claim + evidence + (when mechanical) a fix — the evidence bar is the design rule, see <a href="/mimus/explanation/architecture.html">architecture</a>.</p><h2 id="_4-author-a-convention" tabindex="-1">4. Author a convention <a class="header-anchor" href="#_4-author-a-convention" aria-label="Permalink to &quot;4. Author a convention&quot;">​</a></h2><p><code>rules/</code> is data. Add <code>rules/no-todos.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no-todos&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">message = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TODO left in committed source&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">severity = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warn&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">files = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/**/*.rs&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;source-pattern&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TODO|FIXME&quot;</span></span></code></pre></div><p><code>mimus check</code> now flags every TODO — a convention encoded as a file, not a code change. See <a href="/mimus/how-to/rules-authoring.html">authoring rules</a>.</p><h2 id="_5-audit-the-memory-layer" tabindex="-1">5. Audit the memory layer <a class="header-anchor" href="#_5-audit-the-memory-layer" aria-label="Permalink to &quot;5. Audit the memory layer&quot;">​</a></h2><p>If the repo is kuda-indexed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fresh        kuda-store</span></span>
<span class="line"><span>drifted      kuda-core</span></span>
<span class="line"><span>20 fresh, 1 drifted, 0 contradicted</span></span></code></pre></div><p>Cards whose <code>verify:</code> files changed since sync report <code>drifted</code>; missing files report <code>contradicted</code>.</p><h2 id="what-you-now-know" tabindex="-1">What you now know <a class="header-anchor" href="#what-you-now-know" aria-label="Permalink to &quot;What you now know&quot;">​</a></h2><ul><li><code>mimus init</code> scaffolds <code>mimus.toml</code> (sources, <code>[check]</code> tiers) plus a <code>rules/</code> dir of data-driven conventions.</li><li><code>check</code> extracts factual claims from docs and verifies them against the filesystem, PATH, and the kuda index — violations are claim + evidence + fix, and <code>error</code> severity gates CI.</li><li><code>rules/*.toml</code> encode conventions without code changes; <code>audit</code> checks kuda card freshness (<code>fresh</code>/<code>drifted</code>/ <code>contradicted</code>).</li></ul><p>You have built a falsification layer: every factual claim in your docs is now a test that fails loudly when reality moves.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><strong>How-to</strong> (tasks): <a href="/mimus/how-to/kuda-audit.html">memory audit</a> · <a href="/mimus/how-to/rules-authoring.html">rules authoring</a> · <a href="/mimus/how-to/ci-gate.html">CI gate</a> · <a href="/mimus/how-to/multi-repo.html">multi-repo</a></li><li><strong>Reference</strong> (lookup): <a href="/mimus/reference/cli.html">cli</a> · <a href="/mimus/reference/config.html">config</a> · <a href="/mimus/reference/crate-api.html">crate api</a></li><li><strong>Explanation</strong> (why): <a href="/mimus/explanation/architecture.html">architecture</a> · <a href="/mimus/explanation/concepts.html">concepts</a> · <a href="/mimus/explanation/claims.html">claims &amp; tiers</a> · <a href="/mimus/explanation/decisions.html">decisions</a> · <a href="/mimus/explanation/release-model.html">release model</a> · <a href="/mimus/comparison.html">comparison</a> — vs linters / LLM review</li></ul>`,37)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
